class Solution {
public:
    long long countPrefixSuffixPairs(vector<string>& words) {
        long long ans = 0;
        for (int j = 0; j < (int)words.size(); j++)
            for (int i = 0; i < j; i++)
                if (words[j].rfind(words[i], 0) == 0 &&
                    words[j].compare(words[j].size() - words[i].size(), words[i].size(), words[i]) == 0)
                    ans++;
        return ans;
    }
};

