    def countPrefixSuffixPairs(self, words: List[str]) -> int:
        MOD, B = 2147483647, 131
        seen = {}
        ans = 0
        for w in words:
            n = len(w)
            pre = [0] * (n + 1)
            suf = [0] * (n + 1)
            pw = [1] * (n + 1)
            for i in range(n):
                pre[i + 1] = (pre[i] * B + ord(w[i])) % MOD
                pw[i + 1] = pw[i] * B % MOD
            for i in range(n - 1, -1, -1):
                suf[i] = (suf[i + 1] + ord(w[i]) * pw[n - 1 - i]) % MOD
            for l in range(1, n + 1):
                for c in seen.get(pre[l], ()):
                    if len(c) == l and suf[l] == pre[l] and w.startswith(c) and w.endswith(c):
                        ans += 1
            seen.setdefault(pre[n], []).append(w)
        return ans

