class Solution {
public:
    long long countPrefixSuffixPairs(vector<string>& words) {
        const long long MOD = 2147483647, B = 131;
        unordered_map<long long, vector<string>> seen;
        long long ans = 0;
        for (auto& w : words) {
            int n = w.size();
            vector<long long> pre(n + 1, 0), suf(n + 1, 0), pw(n + 1, 1);
            for (int i = 0; i < n; i++) {
                pre[i + 1] = (pre[i] * B + w[i]) % MOD;
                pw[i + 1] = pw[i] * B % MOD;
            }
            for (int i = n - 1; i >= 0; i--) suf[i] = (suf[i + 1] + w[i] * pw[n - 1 - i]) % MOD;
            for (int l = 1; l <= n; l++) {
                auto it = seen.find(pre[l]);
                if (it == seen.end()) continue;
                for (auto& c : it->second)
                    if ((int)c.size() == l && suf[l] == pre[l] &&
                        w.rfind(c, 0) == 0 && w.compare(n - l, l, c) == 0) ans++;
            }
            seen[pre[n]].push_back(w);
        }
        return ans;
    }
};

