class Solution {
    public long countPrefixSuffixPairs(String[] words) {
        long MOD = 2147483647, B = 131, ans = 0;
        Map<Long, List<String>> seen = new HashMap<>();
        for (String w : words) {
            int n = w.length();
            long[] pre = new long[n + 1], suf = new long[n + 1], pw = new long[n + 1];
            pw[0] = 1;
            for (int i = 0; i < n; i++) {
                pre[i + 1] = (pre[i] * B + w.charAt(i)) % MOD;
                pw[i + 1] = pw[i] * B % MOD;
            }
            for (int i = n - 1; i >= 0; i--) suf[i] = (suf[i + 1] + w.charAt(i) * pw[n - 1 - i]) % MOD;
            for (int l = 1; l <= n; l++)
                for (String c : seen.getOrDefault(pre[l], Collections.emptyList()))
                    if (c.length() == l && suf[l] == pre[l] && w.startsWith(c) && w.endsWith(c)) ans++;
            seen.computeIfAbsent(pre[n], z -> new ArrayList<>()).add(w);
        }
        return ans;
    }
}

